/**
 * Geometry of the conditions tree. Lines and chips share ONE coordinate
 * system (the viewBox): the SVG draws the lines, and each chip is placed at
 * x/w and y/h percent of the same box. The chips are sized in container
 * units (cqw), so the whole thing is a true scaled drawing at any width.
 *
 * The tree is mirror-symmetric about its centre axis. Each breakpoint
 * describes the LEFT half (plus the centred chips) and the right half is
 * generated by mirroring x to w - x, so symmetry cannot drift.
 *
 * It is drawn like a hand-drawn broadleaf tree: a big leafy canopy whose
 * edge is a row of small curls, a thick trunk that tapers upward and forks
 * into two arms at the top, a flared base, and a little bark.
 *
 * Naming follows the map's data: "fruits" are the top chips (SYMPTOMS in
 * root-map.ts), "symptoms" are the middle chips (CONDITIONS there), and
 * "roots" are the bottom chips.
 */

export interface Pt {
  readonly x: number;
  readonly y: number;
}

/** A root chip and the curve that reaches its top-centre from the trunk base. */
export interface RootGeo extends Pt {
  readonly start: Pt;
  readonly c1: Pt;
  readonly c2: Pt;
}

/**
 * The canopy is a round, leafy crown: a smooth squared-off oval (`p` is how
 * square: 2 is an ellipse) whose edge is drawn as a row of small curls,
 * with a few leaf ticks inside it. `rows` are the vertical bands of the
 * fruit chips (and how far each reaches from the axis), so the ticks keep
 * off them, and `armClear` is the strip under the cluster left clear for
 * the trunk's arms.
 */
export interface Canopy {
  readonly cx: number;
  readonly cy: number;
  readonly rx: number;
  readonly ry: number;
  readonly p: number;
  /** Length of one curl along the edge. */
  readonly curl: number;
  readonly rows: readonly { readonly top: number; readonly bottom: number; readonly half: number }[];
  readonly armClear: number;
}

/** The two arms the trunk forks into at the top: how far out and up the tips reach, and how thick each arm is. */
export interface Fork {
  readonly dx: number;
  readonly rise: number;
  readonly w: number;
}

/** A short stroke of bark: how far across the trunk it sits (-1 left edge, 1 right edge) and where along the trunk it runs (0 top, 1 base). */
export interface Bark {
  readonly off: number;
  readonly from: number;
  readonly to: number;
}

export interface TreeGeo {
  readonly w: number;
  readonly h: number;
  /** Chip font size, height and side padding, in cqw (percent of the tree's width). */
  readonly fs: number;
  readonly ch: number;
  readonly pad: number;
  readonly canopy: Canopy;
  readonly fruits: Readonly<Record<string, Pt>>;
  readonly symptoms: Readonly<Record<string, Pt>>;
  /** Where each symptom's branch leaves the trunk edge. */
  readonly attach: Readonly<Record<string, Pt>>;
  readonly roots: Readonly<Record<string, RootGeo>>;
  /** Where the trunk forks (its top), and its half-width there and at the base. */
  readonly trunkTop: Pt;
  readonly trunkHalfTop: number;
  readonly trunkHalfBase: number;
  /** How far the base flares out along the ground. */
  readonly flare: number;
  readonly fork: Fork;
  readonly bark: readonly Bark[];
  readonly groundY: number;
  readonly groundX: readonly [number, number];
  readonly howLabel: Pt;
  readonly whyLabel: Pt;
}

/** What one breakpoint specifies: the left half, and the fruits written out in full. */
interface TreeSpec {
  readonly w: number;
  readonly h: number;
  readonly fs: number;
  readonly ch: number;
  readonly pad: number;
  readonly canopy: Canopy;
  readonly fruits: Readonly<Record<string, Pt>>;
  /** How far everything below the canopy sits higher than the coordinates written here. */
  readonly lift: number;
  /** Left-half symptoms, plus the centred one. */
  readonly symptomsLeft: Readonly<Record<string, Pt>>;
  readonly symptomCentre: Readonly<Record<string, Pt>>;
  /** Height at which each symptom's branch leaves the trunk (left and right share it). */
  readonly attachY: Readonly<Record<string, number>>;
  readonly rootsLeft: Readonly<Record<string, RootGeo>>;
  readonly trunkTop: Pt;
  readonly trunkHalfTop: number;
  readonly trunkHalfBase: number;
  readonly flare: number;
  readonly fork: Fork;
  readonly bark: readonly Bark[];
  readonly groundY: number;
  readonly groundInset: number;
  readonly howLabel: Pt;
  readonly whyLabel: Pt;
}

/** Left chip to its mirrored right chip. */
const PAIRS = {
  symptoms: { inflammation: 'hormonal', digestion: 'nervous' },
  roots: { deficiency: 'toxins', stress: 'sleep', infections: 'genetics' },
} as const;

const mirrorPt = (p: Pt, w: number): Pt => ({ x: w - p.x, y: p.y });

/** The trunk's edge x at height y: straight and widening toward the base, so branches can peel off it exactly. */
function trunkEdge(s: TreeSpec, side: 1 | -1, y: number): number {
  const t = Math.min(1, Math.max(0, (y - s.trunkTop.y) / (s.groundY - 30 - s.trunkTop.y)));
  return s.w / 2 + side * (s.trunkHalfTop + (s.trunkHalfBase - s.trunkHalfTop) * t);
}

function build(spec: TreeSpec): TreeGeo {
  const L = spec.lift;
  const up = (p: Pt): Pt => ({ x: p.x, y: p.y - L });
  const s: TreeSpec = {
    ...spec,
    symptomsLeft: Object.fromEntries(Object.entries(spec.symptomsLeft).map(([k, p]) => [k, up(p)])),
    symptomCentre: Object.fromEntries(Object.entries(spec.symptomCentre).map(([k, p]) => [k, up(p)])),
    attachY: Object.fromEntries(Object.entries(spec.attachY).map(([k, y]) => [k, y - L])),
    rootsLeft: Object.fromEntries(
      Object.entries(spec.rootsLeft).map(([k, r]) => [k, { ...up(r), start: up(r.start), c1: up(r.c1), c2: up(r.c2) }]),
    ),
    trunkTop: up(spec.trunkTop),
    groundY: spec.groundY - L,
    howLabel: up(spec.howLabel),
    whyLabel: up(spec.whyLabel),
    h: spec.h - L,
  };
  const symptoms: Record<string, Pt> = { ...s.symptomCentre };
  const attach: Record<string, Pt> = {};
  for (const [l, r] of Object.entries(PAIRS.symptoms)) {
    symptoms[l] = s.symptomsLeft[l];
    symptoms[r] = mirrorPt(s.symptomsLeft[l], s.w);
    attach[l] = { x: trunkEdge(s, -1, s.attachY[l]), y: s.attachY[l] };
    attach[r] = { x: trunkEdge(s, 1, s.attachY[l]), y: s.attachY[l] };
  }
  for (const id of Object.keys(s.symptomCentre)) {
    attach[id] = { x: s.w / 2, y: s.attachY[id] };
  }

  const roots: Record<string, RootGeo> = {};
  for (const [l, r] of Object.entries(PAIRS.roots)) {
    const a = s.rootsLeft[l];
    roots[l] = a;
    roots[r] = { ...mirrorPt(a, s.w), start: mirrorPt(a.start, s.w), c1: mirrorPt(a.c1, s.w), c2: mirrorPt(a.c2, s.w) };
  }

  return {
    w: s.w,
    h: s.h,
    fs: s.fs,
    ch: s.ch,
    pad: s.pad,
    canopy: s.canopy,
    fruits: s.fruits,
    symptoms,
    attach,
    roots,
    trunkTop: s.trunkTop,
    trunkHalfTop: s.trunkHalfTop,
    trunkHalfBase: s.trunkHalfBase,
    flare: s.flare,
    fork: s.fork,
    bark: s.bark,
    groundY: s.groundY,
    groundX: [s.groundInset, s.w - s.groundInset],
    howLabel: s.howLabel,
    whyLabel: s.whyLabel,
  };
}

/** Desktop fruits as rows centred on the axis: a centre chip sits on x = 500, a pair at 500 -/+ d (so each pair mirrors). */
function desktopFruits(): Record<string, Pt> {
  const pair = (a: string, b: string, y: number, d: number): Record<string, Pt> => ({
    [a]: { x: 500 - d, y },
    [b]: { x: 500 + d, y },
  });
  return {
    ...pair('immune', 'hormones', 109, 161),
    ...pair('gut', 'sugar', 176.7, 185),
    skin: { x: 500, y: 176.7 },
    ...pair('fertility', 'brain', 244.4, 137),
  };
}

