export interface TreePath {
  readonly key: string;
  readonly d: string;
}

export interface TwigPath extends TreePath {
  /** The fruit (top chip) this twig hangs from, and the symptom it leads to. */
  readonly fruit: string;
  readonly symptom: string;
}

export interface TreeArt {
  /** The canopy's whole outline, closed (never drawn: it is the area the fruit chips must sit inside). */
  readonly canopyFill: string;
  /** The canopy's edge as separate curls, some hooking inward and some leaving a gap, like a pencil sketch. */
  readonly canopy: string;
  /** Small leaf ticks just inside the canopy's edge. */
  readonly ticks: string;
  /** The trunk's two outer edges (each running up into the outer edge of an arm). */
  readonly trunkLeft: string;
  readonly trunkRight: string;
  /** The inner edges of the two arms, meeting in the notch between them. */
  readonly arms: string;
  readonly bark: readonly string[];
  /** The line the blue path follows down the trunk. */
  readonly trunk: string;
  readonly ground: string;
  readonly twigs: readonly TwigPath[];
  /** Grey branches (the centred symptom sits on the trunk, so has none) and the blue branch stages (all five). */
  readonly branches: readonly TreePath[];
  readonly blueBranches: readonly TreePath[];
  readonly roots: readonly TreePath[];
}

const f = (n: number): string => String(Math.round(n * 10) / 10);

function cubic(a: Pt, c1: Pt, c2: Pt, b: Pt): string {
  return `M${f(a.x)},${f(a.y)} C${f(c1.x)},${f(c1.y)} ${f(c2.x)},${f(c2.y)} ${f(b.x)},${f(b.y)}`;
}

/**
 * How far each curl's stroke runs past the end it shares with its neighbour,
 * as a share of the curl's own arc: positive hooks inward, negative stops
 * short and leaves a gap. Indexed down the right half and mirrored (with the
 * two ends swapped), so both sides match.
 */
const CURL_STARTS = [0.0, 0.22, -0.08, 0.1, 0.3, -0.04, 0.16];
const CURL_ENDS = [0.28, -0.06, 0.12, 0.34, 0.02, 0.2, -0.1, 0.14, 0.26];

interface CanopyShape {
  readonly fill: string;
  readonly edge: string;
  readonly ticks: string;
}

/**
 * The crown. `fill` is its smooth outline, closed (never drawn: it is the
 * area the fruit chips must sit inside). `edge` is that outline redrawn as a
 * row of small outward curls, some hooking inward and some leaving a gap, like
 * a pencil sketch. `ticks` are little leaf marks inside, kept off the chips.
 * Everything is built for the right half and mirrored, so it is symmetric.
 */
function canopy(c: Canopy): CanopyShape {
  // The outline, sampled finely from the top centre round clockwise.
  const samples = 960;
  const outline: Pt[] = [];
  for (let i = 0; i <= samples; i++) {
    const a = -Math.PI / 2 + (2 * Math.PI * i) / samples;
    const cs = Math.cos(a);
    const sn = Math.sin(a);
    outline.push({
      x: c.cx + c.rx * Math.sign(cs) * Math.abs(cs) ** (2 / c.p),
      y: c.cy + c.ry * Math.sign(sn) * Math.abs(sn) ** (2 / c.p),
    });
  }
  const total: number[] = [0];
  for (let i = 1; i < outline.length; i++) {
    total.push(total[i - 1] + Math.hypot(outline[i].x - outline[i - 1].x, outline[i].y - outline[i - 1].y));
  }
  const length = total[total.length - 1];
  const count = Math.max(8, 2 * Math.round(length / (2 * c.curl)));
  const at = (d: number): Pt => {
    let i = 1;
    while (i < total.length - 1 && total[i] < d) {
      i++;
    }
    const t = (d - total[i - 1]) / (total[i] - total[i - 1] || 1);
    return { x: outline[i - 1].x + (outline[i].x - outline[i - 1].x) * t, y: outline[i - 1].y + (outline[i].y - outline[i - 1].y) * t };
  };
  const q: Pt[] = [];
  for (let k = 0; k < count; k++) {
    q.push(at((length * k) / count));
  }
  const fill = `M${q.map((p) => `${f(p.x)},${f(p.y)}`).join(' L')}Z`;

  const halfCount = count / 2;
  let edge = '';
  for (let k = 0; k < count; k++) {
    const a = q[k];
    const b = q[(k + 1) % count];
    const m = k < halfCount ? k : count - 1 - k;
    const chord = Math.hypot(b.x - a.x, b.y - a.y);
    const radius = chord * (m % 2 === 0 ? 0.62 : 0.8);
    // Travelling clockwise, outward is to the left of the way we go.
    const tx = (b.x - a.x) / chord;
    const ty = (b.y - a.y) / chord;
    const depth = Math.sqrt(Math.max(0, radius * radius - (chord * chord) / 4));
    const centre = { x: (a.x + b.x) / 2 - ty * depth, y: (a.y + b.y) / 2 + tx * depth };
    const a1 = Math.atan2(a.y - centre.y, a.x - centre.x);
    const a2 = Math.atan2(b.y - centre.y, b.x - centre.x);
    const sweep = (a2 - a1 + 2 * Math.PI) % (2 * Math.PI);
    const first = k < halfCount ? CURL_STARTS[m % CURL_STARTS.length] : CURL_ENDS[m % CURL_ENDS.length];
    const last = k < halfCount ? CURL_ENDS[m % CURL_ENDS.length] : CURL_STARTS[m % CURL_STARTS.length];
    const s = a1 - first * sweep;
    const e = a2 + last * sweep;
    const span = sweep * (1 + first + last);
    const pt = (angle: number): string => `${f(centre.x + radius * Math.cos(angle))},${f(centre.y + radius * Math.sin(angle))}`;
    edge += `M${pt(s)} A${f(radius)},${f(radius)} 0 ${span > Math.PI ? 1 : 0} 1 ${pt(e)} `;
  }

  // Leaf ticks inside, off the chips and off the strip the trunk's arms reach up into.
  const lastRow = c.rows[c.rows.length - 1];
  const size = c.curl * 0.42;
  const clear = (p: Pt): boolean =>
    !c.rows.some((r) => p.y > r.top - 14 && p.y < r.bottom + 14 && Math.abs(p.x - c.cx) < r.half + 22) &&
    !(p.y > lastRow.bottom && Math.abs(p.x - c.cx) < c.armClear);
  let ticks = '';
  const tick = (p: Pt, kind: number): string =>
    kind % 2 === 0
      ? `M${f(p.x - size)},${f(p.y - size * 0.35)} Q${f(p.x - size * 0.55)},${f(p.y + size * 0.65)} ${f(p.x)},${f(p.y - size * 0.1)} Q${f(p.x + size * 0.55)},${f(p.y + size * 0.65)} ${f(p.x + size)},${f(p.y - size * 0.35)} `
      : `M${f(p.x - size)},${f(p.y - size * 0.4)} Q${f(p.x)},${f(p.y + size * 0.9)} ${f(p.x + size)},${f(p.y - size * 0.4)} `;
  for (let k = 0; k <= halfCount; k++) {
    if (k % 3 !== 1 && k !== 0) {
      continue;
    }
    const shrink = k % 2 === 0 ? 0.84 : 0.7;
    const p = { x: c.cx + (q[k % count].x - c.cx) * shrink, y: c.cy + (q[k % count].y - c.cy) * shrink };
    if (!clear(p)) {
      continue;
    }
    ticks += tick(p, k);
    if (Math.abs(p.x - c.cx) > 1) {
      ticks += tick({ x: 2 * c.cx - p.x, y: p.y }, k);
    }
  }

  return { fill, edge: edge.trim(), ticks: ticks.trim() };
}

/** Every line of the tree, each drawn in the direction the traced path travels: fruit, symptom, trunk, root. */
export function buildTree(
  g: TreeGeo,
  links: {
    readonly fruitToSymptom: Readonly<Record<string, readonly string[]>>;
  },
): TreeArt {
  const half = (g.ch / 100) * g.w * 0.5;

  const twigs: TwigPath[] = [];
  for (const [fruit, symptoms] of Object.entries(links.fruitToSymptom)) {
    const a = g.fruits[fruit];
    for (const symptom of symptoms) {
      const b = g.symptoms[symptom];
      const start = { x: a.x, y: a.y + half };
      const end = { x: b.x, y: b.y - half };
      const mid = (start.y + end.y) / 2;
      twigs.push({
        key: `${fruit}>${symptom}`,
        fruit,
        symptom,
        d: cubic(start, { x: start.x, y: mid }, { x: end.x, y: mid }, end),
      });
    }
  }

  // Each branch peels off the trunk edge (arriving along it, vertically) and sweeps out to its chip's bottom-centre.
  const blueBranches: TreePath[] = Object.keys(g.symptoms).map((id) => {
    const s = g.symptoms[id];
    const a = g.attach[id];
    const start = { x: s.x, y: s.y + half };
    const lift = Math.max(10, Math.abs(a.y - start.y) * 0.5);
    return { key: id, d: cubic(start, { x: start.x, y: start.y + lift }, { x: a.x, y: a.y - lift }, a) };
  });
  const branches = blueBranches.filter((b) => Math.abs(g.symptoms[b.key].x - g.w / 2) > 1);

  const roots: TreePath[] = Object.entries(g.roots).map(([id, r]) => ({
    key: id,
    d: cubic(r.start, r.c1, r.c2, { x: r.x, y: r.y - half }),
  }));

  // The trunk: from the flared base up the (straight, tapering) edge, then out along the outer edge of an arm.
  const top = g.trunkTop;
  const yBase = g.groundY - 30;
  const w0 = g.trunkHalfTop;
  const w1 = g.trunkHalfBase;
  const fk = g.fork;
  const X = (sign: 1 | -1, off: number): number => top.x + sign * off;
  const trunkSide = (sign: 1 | -1): string =>
    `M${f(X(sign, w1 + g.flare))},${f(g.groundY)} C${f(X(sign, w1 + g.flare * 0.35))},${f(g.groundY - 1)} ${f(X(sign, w1))},${f(g.groundY - 8)} ${f(X(sign, w1))},${f(yBase)} L${f(X(sign, w0))},${f(top.y)} C${f(X(sign, w0 + 3))},${f(top.y - fk.rise * 0.45)} ${f(X(sign, fk.dx - 14))},${f(top.y - fk.rise * 0.85)} ${f(X(sign, fk.dx))},${f(top.y - fk.rise)}`;
  const arm = (sign: 1 | -1): string =>
    `M${f(X(sign, fk.dx - fk.w))},${f(top.y - fk.rise - 7)} C${f(X(sign, fk.dx - fk.w - 12))},${f(top.y - fk.rise * 0.6)} ${f(X(sign, 10))},${f(top.y - fk.rise * 0.45)} ${f(X(sign, 3))},${f(top.y - 14)}`;

  const length = yBase - top.y;
  const widthAt = (y: number): number => w0 + (w1 - w0) * Math.min(1, Math.max(0, (y - top.y) / length));
  const bark = g.bark.map((b) => {
    const y0 = top.y + b.from * length;
    const y1 = top.y + b.to * length;
    const x = (y: number, wobble: number): number => top.x + b.off * widthAt(y) + wobble;
    const ya = y0 + (y1 - y0) * 0.3;
    const yb = y0 + (y1 - y0) * 0.7;
    return `M${f(x(y0, 0))},${f(y0)} C${f(x(ya, 3))},${f(ya)} ${f(x(yb, -3))},${f(yb)} ${f(x(y1, 0))},${f(y1)}`;
  });

  const shape = canopy(g.canopy);
  return {
    canopyFill: shape.fill,
    canopy: shape.edge,
    ticks: shape.ticks,
    trunkLeft: trunkSide(-1),
    trunkRight: trunkSide(1),
    arms: `${arm(-1)} ${arm(1)}`,
    bark,
    trunk: cubic({ x: top.x, y: top.y - 14 }, { x: top.x, y: top.y + length * 0.3 }, { x: top.x, y: g.groundY - length * 0.3 }, { x: top.x, y: g.groundY }),
    ground: `M${g.groundX[0]},${g.groundY} L${g.groundX[1]},${g.groundY}`,
    twigs,
    branches,
    blueBranches,
    roots,
  };
}
